const deadline=Date.parse('2026-10-22T09:34:39.819Z');
const log=[];
const sw=sdk.findInventoryItem(/bronze sword/i); if(sw) await bot.equipItem(sw);
function best(re){ const ns=sdk.getState().nearbyNpcs.filter(n=>re.test(n.name)&&n.reachable!==false); return ns.sort((a,b)=>(b.combatLevel||0)-(a.combatLevel||0))[0]||null; }
const t0=Date.now();
while(Date.now()<deadline-2500){
  const st=sdk.getState();
  if(st.player.hp<=0){ log.push('died'); break; }
  const t=best(/^Imp$/i)||best(/^Man$/i);
  if(!t){ await sdk.waitForTicks(1); continue; }
  if(!(st.player.combat.inCombat && st.player.combat.targetIndex===t.index)) await bot.attack(t,2000);
  await sdk.waitForTicks(1);
}
log.push('hp:'+sdk.getState().player.hp+' secLeft:'+Math.round((deadline-Date.now())/1000));
return log;
